import struct,glob
def dims(p):
    b=open(p,'rb').read(64)
    if b[:4]==b'\x89PNG': return struct.unpack('>II',b[16:24])
    if b[:4]==b'RIFF':
        t=b[12:16]
        if t==b'VP8X': return (1+int.from_bytes(b[24:27],'little'),1+int.from_bytes(b[27:30],'little'))
        if t==b'VP8 ': w,h=struct.unpack('<HH',b[26:30]); return (w&0x3fff,h&0x3fff)
        if t==b'VP8L':
            v=int.from_bytes(b[21:25],'little'); return ((v&0x3fff)+1,((v>>14)&0x3fff)+1)
    if b[:2]==b'\xff\xd8': return 'jpeg'
for p in sorted(glob.glob('before/*'))+['assets/store/choose-master-severin.jpg','assets/store/hero-guardian.webp','assets/store/portrait-guardian.webp','assets/store/map-mf-ford-tutorial.webp','assets/store/icon-attack.webp','assets/store/backdrop-ford.webp']:
    print(p,dims(p))
